WITH targets AS (SELECT oid,relname,relrowsecurity,relforcerowsecurity,relacl FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN('clients','installations','inventory_categories','inventory_movements','inventory_products','inventory_unit_events','inventory_units','job_assignees','job_work_sessions','profiles','routine_returns','routines','service_contracts','tickets'))
 SELECT jsonb_build_object('at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'origin',current_database()='postgres' AND current_user='postgres' AND current_setting('session_replication_role')='origin',
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_md5',md5(replace(pg_get_functiondef(p.oid),E'\r','')),'acl',p.proacl)) FROM pg_proc p WHERE p.oid IN(SELECT to_regprocedure(s) FROM unnest(ARRAY['auth.uid()','current_user_role()','set_updated_at()','set_contract_number()','set_ticket_number()','set_ticket_status_timestamps()','set_installation_completed_at()','apply_inventory_movement()','apply_inventory_unit_event()','guard_inventory_product_deactivation()','validate_installation_completion()','set_ticket_imputabilidad()','reverse_inventory_on_installation_delete()','reverse_inventory_on_installation_cancel()','reverse_inventory_on_ticket_delete()','guard_inventory_units_onu_limit_on_contract_update()','guard_tecnico_no_cambia_prioridad()','sync_assigned_to_from_job_assignees()','set_routine_number()','set_routine_status_timestamps()','reset_alerta_enviada()','enforce_single_active_job()','enforce_single_active_job_assignees()','track_job_work_session()','free_nap_puerto_on_contract_delete()','free_nap_puerto_on_client_delete()','return_routine(uuid,text)','assert_current_job_operator(text,uuid)','guard_job_completion_crew()','lock_job_crew_parent()','set_current_job_crew(text,uuid,jsonb,jsonb)','find_other_active_job(uuid,text,uuid)','generate_contract_number()','generate_routine_number()','generate_ticket_number()','reverse_assigned_units_by_installation(uuid,text)','reverse_egreso_movements(uuid,uuid,text)'])s)),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',t.relname,'rls',t.relrowsecurity,'force',t.relforcerowsecurity,'acl',t.relacl,
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'default',pg_get_expr(d.adbin,d.adrelid),'not_null',a.attnotnull) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid))) FROM pg_constraint WHERE conrelid=t.oid),
 'indexes',(SELECT jsonb_agg(pg_get_indexdef(indexrelid)) FROM pg_index WHERE indrelid=t.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid),'function',tgfoid::regprocedure::text)) FROM pg_trigger WHERE tgrelid=t.oid AND NOT tgisinternal))) FROM targets t),
 'policies',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='public' AND tablename IN(SELECT relname FROM targets)),
 'types',(SELECT jsonb_agg(jsonb_build_object('name',t.typname,'values',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid))) FROM pg_type t WHERE t.typnamespace='public'::regnamespace AND t.typtype='e' AND t.oid IN(SELECT a.atttypid FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM targets) AND a.attnum>0)),
 'fase162_absent',to_regclass('public.routine_inventory_operations') IS NULL AND NOT EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('routine_inventory_operation','check_routine_inventory_receipt','guard_routine_inventory_movement','guard_routine_inventory_unit','guard_routine_inventory_event','apply_routine_inventory_event')) AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid IN('public.inventory_movements'::regclass,'public.inventory_unit_events'::regclass,'public.inventory_units'::regclass) AND attname IN('routine_id','operation_id') AND NOT attisdropped)
 )
